export type MessageText = { text: string; start: number };
export type MessageBlock =
  | ({ kind: "text" } & MessageText)
  | { kind: "ul" | "ol"; number: number; items: MessageText[] };

/** A small, shared formatting subset: bold, bullets, and numbered lists. */
export function messageBlocks(body: string): MessageBlock[] {
  const blocks: MessageBlock[] = [];
  let offset = 0;
  for (const line of body.split(/\r\n|\r|\n/)) {
    const bullet = /^\s*(?:[-*] |(\d+)\. )(.+)$/.exec(line);
    const previous = blocks.at(-1);
    if (bullet) {
      const kind = bullet[1] ? "ol" : "ul";
      const item = {
        text: bullet[2],
        start: offset + line.length - bullet[2].length,
      };
      if (previous?.kind === kind) previous.items.push(item);
      else blocks.push({ kind, number: Number(bullet[1] ?? 1), items: [item] });
    } else if (previous?.kind === "text") {
      previous.text = body.slice(previous.start, offset + line.length);
    } else blocks.push({ kind: "text", text: line, start: offset });
    const newline =
      body.slice(offset + line.length).match(/^(\r\n|\r|\n)/)?.[0] ?? "";
    offset += line.length + newline.length;
  }
  return blocks;
}

export function messageInline({ text, start }: MessageText) {
  const fragments: (MessageText & { bold: boolean })[] = [];
  let cursor = 0;
  for (const match of text.matchAll(/\*\*([^\r\n]+?)\*\*/g)) {
    if (match.index > cursor)
      fragments.push({
        text: text.slice(cursor, match.index),
        start: start + cursor,
        bold: false,
      });
    fragments.push({
      text: match[1],
      start: start + match.index + 2,
      bold: true,
    });
    cursor = match.index + match[0].length;
  }
  if (cursor < text.length)
    fragments.push({
      text: text.slice(cursor),
      start: start + cursor,
      bold: false,
    });
  return fragments;
}
